package java.util.concurrent;
public final class Executors {private Executors(){} public static ExecutorService newSingleThreadExecutor(){return new SimpleExecutor();} public static ExecutorService newFixedThreadPool(int n){if(n<=0)throw new IllegalArgumentException();return new SimpleExecutor();} public static ExecutorService newCachedThreadPool(){return new SimpleExecutor();} public static ExecutorService newWorkStealingPool(){return new SimpleExecutor();} public static ExecutorService newWorkStealingPool(int n){if(n<=0)throw new IllegalArgumentException();return new SimpleExecutor();} public static Callable<Object> callable(final Runnable r){return callable(r,null);} public static <T> Callable<T> callable(final Runnable r,final T result){if(r==null)throw new NullPointerException();return new Callable<T>(){public T call(){r.run();return result;}};} public static ThreadFactory defaultThreadFactory(){return new ThreadFactory(){public Thread newThread(Runnable r){return new Thread(r);}};}
 public static ScheduledExecutorService newScheduledThreadPool(int n){return new ScheduledThreadPoolExecutor(n);} public static ScheduledExecutorService newScheduledThreadPool(int n,ThreadFactory f){return new ScheduledThreadPoolExecutor(n,f);} public static ScheduledExecutorService newSingleThreadScheduledExecutor(){return new ScheduledThreadPoolExecutor(1);} public static ScheduledExecutorService newSingleThreadScheduledExecutor(ThreadFactory f){return new ScheduledThreadPoolExecutor(1,f);}
 static class SimpleExecutor extends AbstractExecutorService {boolean shutdown;public void execute(Runnable r){if(r==null)throw new NullPointerException();if(shutdown)throw new RejectedExecutionException();new Thread(r).start();} public void shutdown(){shutdown=true;} public java.util.List<Runnable> shutdownNow(){shutdown=true;return new java.util.ArrayList<Runnable>();}public boolean isShutdown(){return shutdown;}public boolean isTerminated(){return shutdown;}public boolean awaitTermination(long n,TimeUnit u)throws InterruptedException {if(u==null)throw new NullPointerException();java.lang.VMThread.runPending();return shutdown;}}
}
